import sys

def find_profile(mask):
    n = len(mask)
    profile = []
    i = 0
    while i < n:
        if mask[i] == '#':
            start = i
            while i < n and mask[i] == '#':
                i += 1
            profile.append(i - start)
        else:
            i += 1

    # Check for invalid masks
    if not profile:
        return 0, []

    # Check gaps between filled segments
    prev_end = -1
    for segment in profile:
        gap_start = prev_end + segment + 1
        if gap_start >= n or mask[gap_start] == '#':
            return -1, []
        prev_end = gap_start + 1

    return len(profile), profile

def main():
    import sys
    mask = sys.stdin.read().strip()
    k, profile = find_profile(mask)
    if k == -1:
        print(-1)
    else:
        print(k)
        print(' '.join(map(str, profile)))

if __name__ == "__main__":
    main()
